  ["Arena"] = "Arena",
  ["Arena, nueva pestaña «Taberna»: los Huesos, un juego de dados por puntos (contra la casa para practicar, o contra alguien de la hermandad)."] = "Arena, nova aba «Taverna»: os Ossos, um jogo de dados por pontos (contra a casa para treinar, ou contra alguém da guilda).",
  ["Arena, nueva pestaña «Torneos»: torneos con cuadro eliminatorio y sorteo con /roll, y veladas con combates anunciados."] = "Arena, nova aba «Torneios»: torneios eliminatórios com sorteio por /roll, e noites com lutas anunciadas.",
  ["Arena, «Cara a cara»: dos luchadores frente a frente (puntos, rango, récord, sus combates entre ellos), con su vida en directo si los tienes cerca y quién gana al acabar. Se agranda para retransmitir."] = "Arena, «Cara a cara»: dois lutadores frente a frente (pontos, posto, histórico, as lutas entre eles), com a vida ao vivo se estiverem perto e quem vence no fim. Aumenta para transmitir.",
  ["Arena: %s"] = "Arena: %s",
  ["Arena: en «Retos» salen todos los conectados, y se explica cómo retar. Administración: solo marca en rojo los errores de esta versión."] = "Arena: em «Desafios» aparecem todos os conectados, e explica como desafiar. Administração: só marca em vermelho os erros desta versão.",
  ["Armería"] = "Arsenal",
  ["Armería: cada objeto sale con su nombre y su icono (antes salía «Objeto 6189» con una interrogación). En tu propio equipo, la ventana del objeto ya no sale repetida al lado."] = "Armaria: cada item mostra o seu nome e o seu ícone (antes aparecia «Item 6189» com um ponto de interrogação). No seu próprio equipamento, a janela do item não aparece mais repetida ao lado.",
  ["Armería: la lista del equipo ya no se sale de su panel la primera vez que se abre."] = "Arsenal: a lista do equipamento não sai mais do painel na primeira vez que abre.",
  ["Armería: «Ver su equipo» funciona aunque esté lejos (si tiene BlazonGuild, se lo pedimos). Y en los encargos puedes poner el objeto con Mayús+clic o arrastrándolo."] = "Arsenal: «Ver o equipamento» funciona mesmo de longe (se ele tiver BlazonGuild, pedimos a ele). E nas encomendas você pode pôr o item com Shift+clique ou arrastando.",
  ["Arrastra aquí a quien quede de reserva."] = "Arraste aqui quem ficar na reserva.",
  ["Arrastra cada nombre a su grupo y su fila, o púlsalo y luego pulsa dónde va. Al soltarlo sobre otro, se cambian el sitio."] = "Arraste cada nome para seu grupo e sua linha, ou toque nele e depois onde vai. Ao soltar sobre outro, eles trocam de lugar.",
  ["Arreglado: Artesanía y botín se veía con las pestañas una encima de otra."] = "Corrigido: Artesanato e saque mostrava as abas uma em cima da outra.",
  ["Arreglado: al volver a programar una raid cancelada, seguía cancelada."] = "Corrigido: ao reagendar uma raide cancelada, ela continuava cancelada.",
  ["Arreglado: la Arena y «Se busca» se quedaban a medias (y la Arena enseñaba «Nueva temporada» a todos)."] = "Corrigido: a Arena e «Procurados» ficavam pela metade (e a Arena mostrava «Nova temporada» a todos).",
  ["Arrástralo a un grupo, o púlsalo y luego pulsa dónde va. Clic derecho: sin grupo."] = "Arraste-o para um grupo, ou toque nele e depois onde vai. Clique direito: sem grupo.",
  ["Arrástralo para moverlo por el borde del minimapa. /bg minimapa lo oculta."] = "Arraste-o para movê-lo pela borda do minimapa. /bg minimapa o oculta.",
