  ["Aún nadie ha cazado a un buscado."] = "Ninguém caçou um procurado ainda.",
  ["Aún nadie ha jugado una partida entre miembros. Las de práctica contra la casa no cuentan."] = "Ninguém jogou ainda uma partida entre membros. As de treino contra a casa não contam.",
  ["Aún nadie ha votado. "] = "Ninguém votou ainda. ",
  ["Aún nadie, aparte del jefe."] = "Ninguém ainda, além do chefe.",
  ["Aún nadie."] = "Ninguém ainda.",
  ["Aún nadie. Cuando alguien entra, dice quién le trajo."] = "Ninguém ainda. Quando alguém entra, diz quem o trouxe.",
  ["Aún ninguna. Aquí salen las raids de BlazonGuild que ya empezaron, con cuántos fueron."] = "Nenhuma ainda. Aqui aparecem as raides do BlazonGuild que já começaram, com quantos foram.",
  ["Aún ninguno. Cuando la hermandad mate a un jefe de esta banda (con la mayoría del grupo de la hermandad), el addon de quien estaba allí lo apunta solo."] = "Nenhum ainda. Quando a guilda matar um chefe desta raide (com a maior parte do grupo da guilda), o addon de quem estava lá anota sozinho.",
  ["Aún no compartes tu equipo. Pulsa «Compartir mi equipo» y tu hermandad verá lo que llevas puesto (se actualiza solo cuando cambias algo)."] = "Você ainda não compartilha seu equipamento. Clique em «Compartilhar meu equipamento» e sua guilda verá o que você usa (atualiza sozinho quando você troca algo).",
  ["Aún no conocéis ninguna hermandad. Cuando alguien de la vuestra juegue en grupo con alguien de otra hermandad que use BlazonGuild y publique sus cifras, aparecerá aquí."] = "Vocês ainda não conhecem nenhuma guilda. Quando alguém da sua jogar em grupo com alguém de outra guilda que use o BlazonGuild e publique seus números, ela aparecerá aqui.",
  ["Aún no conocéis otras hermandades. Aparecen al jugar en grupo (mazmorras, bandas, campos de batalla) con alguien de ellas que use BlazonGuild."] = "Vocês ainda não conhecem outras guildas. Elas aparecem ao jogar em grupo (masmorras, raides, campos de batalha) com alguém delas que use o BlazonGuild.",
  ["Aún no ha pasado nada. Aquí sale cada muerte y cada baja que apuntan los miembros con el addon."] = "Ainda não aconteceu nada. Aqui aparece cada morte e cada abate que os membros com o addon anotam.",
  ["Aún no ha peleado esta temporada."] = "Ainda não lutou nesta temporada.",
  ["Aún no ha respondido nadie."] = "Ninguém respondeu ainda.",
  ["Aún no has preguntado nada."] = "Você ainda não perguntou nada.",
  ["Aún no hay campeón: el primero que gane un duelo se lleva el cinturón."] = "Ainda não há campeão: o primeiro que vencer um duelo leva o cinturão.",
  ["Aún no hay cartas. El líder de la alianza escribe aquí a los maestros (y, si quiere, a los capitanes)."] = "Ainda não há cartas. O líder da aliança escreve aqui aos mestres (e, se quiser, aos capitães).",
  ["Aún no hay combates esta temporada."] = "Ainda não há lutas nesta temporada.",
  ["Aún no hay combates esta temporada. Reta a alguien en «Retos», o batíos en duelo desde el juego: el addon de quien pierde lo apunta solo."] = "Ainda não há lutas nesta temporada. Desafie alguém em «Desafios», ou duelem pelo jogo: o addon de quem perde anota sozinho.",
  ["Aún no hay combates.%s"] = "Ainda não há lutas.%s",
  ["Aún no hay escuadras. "] = "Ainda não há esquadrões. ",
  ["Aún no hay escuadras. Crea una con un jefe y unos pocos miembros: tendrá su propio chat y podréis llamarla a operaciones."] = "Ainda não há esquadrões. Crie um com um chefe e poucos membros: terá seu próprio chat e vocês poderão chamá-lo para operações.",
  ["Aún no hay escuadras. Las crean los organizadores; cada una tiene su jefe y su propio chat."] = "Ainda não há esquadrões. Os organizadores os criam; cada um tem seu chefe e seu próprio chat.",
  ["Aún no hay ficha. La escriben los oficiales: a qué os dedicáis, idioma, días de banda y a quién buscáis."] = "Ainda não há ficha. Os oficiais a escrevem: o que vocês fazem, idioma, dias de raide e quem procuram.",
  ["Aún no hay foto del banco. Aparecerá cuando un oficial o un tesorero lo abra con BlazonGuild."] = "Ainda não há foto do banco. Aparecerá quando um oficial ou tesoureiro o abrir com BlazonGuild.",
  ["Aún no hay nadie en este ranking."] = "Ainda não há ninguém neste ranking.",
