  ["Editar raid"] = "Editar raide",
  ["El Templo de Atal'Hakkar"] = "O Templo de Atal'Hakkar",
  ["El artesano"] = "O artesão",
  ["El atajo Mayús + tecla de hermandad"] = "O atalho Shift + tecla da guilda",
  ["El botón de BlazonGuild en la ventana de hermandad del juego"] = "O botão do BlazonGuild na janela de guilda do jogo",
  ["El canal oculto de la alianza (su chat sigue por los mensajeros)"] = "O canal oculto da aliança (o chat continua pelos mensageiros)",
  ["El chat de hermandad del juego no se puede silenciar desde un addon: ahí solo se oculta en BlazonGuild."] = "O chat da guilda do jogo não pode ser silenciado por um addon: lá só é ocultado no BlazonGuild.",
  ["El chat de la alianza va también por un canal oculto del juego, así llega aunque falten mensajeros. Y la pestaña «Gestión» reúne los cargos y las invitaciones."] = "O chat da aliança também passa por um canal oculto do jogo, assim chega mesmo sem mensageiros. E a aba «Gestão» reúne os cargos e os convites.",
  ["El chat de oficiales del juego: solo lo leen los rangos con permiso."] = "O chat de oficiais do jogo: só os postos com permissão leem.",
  ["El equipo, los talentos, los atributos y las profesiones de cada miembro, con sus tooltips, sin salir del juego."] = "O equipamento, os talentos, os atributos e as profissões de cada membro, com suas dicas, sem sair do jogo.",
  ["El escudo de honor en las ventanas de chat del juego"] = "O brasão de honra nas janelas de chat do jogo",
  ["El grupo de %s para %s no puede llevarte esta vez."] = "O grupo de %s para %s não pode te levar desta vez.",
  ["El honor"] = "A honra",
  ["El idioma nuevo se aplica al recargar la interfaz."] = "O novo idioma se aplica ao recarregar a interface.",
  ["El jefe tiene que ser de tu hermandad."] = "O chefe tem que ser da sua guilda.",
  ["El juego"] = "O jogo",
  ["El juego no deja inspeccionarle ahora."] = "O jogo não deixa inspecioná-lo agora.",
  ["El juego no deja que un accesorio recargue la interfaz por sí solo."] = "O jogo não deixa um addon recarregar a interface sozinho.",
  ["El juego no devolvió la tirada (/roll). Vuelve a pulsar «Sortear y empezar»."] = "O jogo não devolveu a rolagem (/roll). Toque de novo em «Sortear e começar».",
  ["El juego no respondió; acércate y vuelve a probar."] = "O jogo não respondeu; aproxime-se e tente de novo.",
  ["El juego solo deja inspeccionar de cerca (unos 30 metros). Desde lejos solo se ve el equipo de quien tiene BlazonGuild: acércate a él, o pídele que lo instale."] = "O jogo só deixa inspecionar de perto (uns 30 metros). De longe só se vê o equipamento de quem tem BlazonGuild: chegue perto ou peça para ele instalar.",
  ["El juego tardaba demasiado en responder; vuelve a pulsar."] = "O jogo demorava demais para responder; toque de novo.",
  ["El juego todavía no ha enviado la lista de miembros. Aparecerá en unos segundos."] = "O jogo ainda não enviou a lista de membros. Ela aparecerá em alguns segundos.",
  ["El libro está vacío. Cuando alguien dé oro a un tesorero por comercio o correo, se apunta aquí solo."] = "O livro está vazio. Quando alguém der ouro a um tesoureiro por troca ou correio, será anotado aqui sozinho.",
  ["El líder"] = "O líder",
  ["El líder de «%s» ha sacado a %s de la alianza."] = "O líder de «%s» tirou %s da aliança.",
  ["El líder puede llamar a las armas a toda la alianza y darle una clave nueva."] = "O líder pode chamar a aliança inteira às armas e dar a ela uma chave nova.",
  ["El líder puede ocultar a alguien en los chats comunes; la lista la ven los organizadores."] = "O líder pode ocultar alguém nos chats comuns; os organizadores veem a lista.",
  ["El maestro"] = "O mestre",
  ["El maestro decide sobre %s"] = "O mestre decide sobre %s",
  ["El maestro ha decidido no mostrar los donantes."] = "O mestre decidiu não mostrar os doadores.",
  ["El maestro ha decidido que el libro solo lo vean los oficiales y los tesoreros."] = "O mestre decidiu que só os oficiais e os tesoureiros veem o livro.",
  ["El maestro la crea e invita a alguien de otra hermandad que tenga BlazonGuild. Su maestro la acepta o la rechaza."] = "O mestre a cria e convida alguém de outra guilda que tenha BlazonGuild. O mestre dela aceita ou recusa.",
  ["El maestro nombra a los capitanes (leen y escriben en «Oficiales de la alianza») y a los mensajeros (llevan los mensajes a las otras hermandades)."] = "O mestre nomeia os capitães (leem e escrevem em «Oficiais da aliança») e os mensageiros (levam as mensagens às outras guildas).",
  ["El maestro nombra a los tesoreros en «Cuotas». Son quienes guardan el oro de la hermandad. El addon nunca mueve oro: solo lo apunta."] = "O mestre nomeia os tesoureiros em «Cotas». São eles que guardam o ouro da guilda. O addon nunca move ouro: só anota.",
  ["El maestro pulsa «Publicar nuestras cifras» en Rankings, pestaña «Hermandades». Se ven al jugar en grupo con alguien de otra hermandad que use BlazonGuild. Solo cifras de la hermandad, nada de nadie en concreto."] = "O mestre clica em «Publicar nossos números» em Rankings, aba «Guildas». Eles são vistos ao jogar em grupo com alguém de outra guilda que use o BlazonGuild. Só números da guilda, nada de ninguém em particular.",
  ["El maestro%s invita a otras hermandades y decide si seguís en la alianza."] = "O mestre%s convida outras guildas e decide se vocês continuam na aliança.",
  ["El mes de la hermandad: raids y eventos de BlazonGuild junto a los del calendario del juego."] = "O mês da guilda: raides e eventos do BlazonGuild junto aos do calendário do jogo.",
  ["El modo capturas ha terminado: vuelves a ver tu hermandad."] = "O modo capturas terminou: você volta a ver sua guilda.",
  ["El parte"] = "O relatório",
  ["El primero de cada ranking lleva ese honor: sale en su ficha, con un escudo dorado sobre su nombre en el juego y junto a lo que escribe en el chat."] = "O primeiro de cada ranking leva essa honra: aparece na ficha dele, com um brasão dourado sobre o nome no jogo e junto ao que escreve no chat.",
  ["El primero de cada ranking lleva su honor: sale en su ficha, con un escudo dorado sobre su nombre y en el chat."] = "O primeiro de cada ranking leva sua honra: aparece na ficha, com um brasão dourado sobre o nome e no chat.",
  ["El punto del minimapa y la flecha ya no gastan nada mientras no hay nada que dibujar."] = "Os pontos do minimapa e a seta não gastam nada enquanto não há nada para desenhar.",
  ["El tesorero"] = "O tesoureiro",
  ["El texto ya nunca queda debajo de los botones de la tarjeta."] = "O texto nunca mais fica debaixo dos botões do cartão.",
  ["Elegir a quién…"] = "Escolher quem…",
  ["Elegir…"] = "Escolher…",
  ["Elige a alguien de tu hermandad."] = "Escolha alguém da sua guilda.",
  ["Elige a cada luchador de la lista (los miembros, por orden alfabético), o escribe parte de su nombre y la lista se queda solo con los que coinciden."] = "Escolha cada lutador da lista (os membros, em ordem alfabética), ou escreva parte do nome e a lista fica só com os que coincidem.",
  ["Elige a dos luchadores distintos."] = "Escolha dois lutadores diferentes.",
  ["Elige a quién retar"] = "Escolha quem desafiar",
  ["Elige el día y la hora."] = "Escolha o dia e a hora.",
  ["Elige la banda, el día y la hora."] = "Escolha a raide, o dia e a hora.",
  ["Elige la banda, el día y la hora. Tu hermandad la verá al instante y se apuntará desde el juego con su rol."] = "Escolha a raide, o dia e a hora. Sua guilda verá na hora e se inscreverá pelo jogo com sua função.",
  ["Elige para qué es el grupo: una mazmorra, una banda u otra actividad."] = "Escolha para que é o grupo: uma masmorra, uma raide ou outra atividade.",
  ["Elige uno a la izquierda, o crea uno con «Nuevo»."] = "Escolha um à esquerda, ou crie um com «Novo».",
  ["Empate"] = "Empate",
  ["Empezar"] = "Começar",
  ["Empezar la temporada %s"] = "Começar a temporada %s",
  ["Empezar la velada"] = "Começar a noite",
  ["Empiezas tú: pulsa «Tirar» en la Taberna."] = "Você começa: toque em «Jogar» na Taverna.",
  ["En %s. "] = "Em %s. ",
  ["En Artesanía y botín: busca el objeto y susurra al artesano o hazle un encargo. Los artesanos publican su profesión al abrirla en el juego."] = "Em Artesanato e saque: busque o item e sussurre para o artesão ou faça uma encomenda. Os artesãos publicam sua profissão ao abri-la no jogo.",
  ["En Mapa, pestaña «Avistamientos», preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora. Nada se envía si nadie pregunta."] = "Em Mapa, aba «Avistamentos», você pergunta onde um jogador da outra facção foi visto. Respondem os colegas que aceitam, com o que viram no último quarto de hora. Nada é enviado se ninguém perguntar.",
  ["En Mapa, pestaña «En el mapa», pulsa «Seguir» junto a su nombre: una flecha bajo el minimapa te lleva hasta él. Sirve con quien comparte su posición y con el punto de reunión."] = "Em Mapa, aba «No mapa», clique em «Seguir» ao lado do nome: uma seta sob o minimapa leva você até ele. Funciona com quem compartilha a posição e com o ponto de encontro.",
  ["En cola"] = "Na fila",
  ["En curso"] = "Em andamento",
  ["En el chat, una pestaña para toda la alianza y otra para cada hermandad hermana; las salas de roles se comparten."] = "No chat, uma aba para a aliança inteira e outra para cada guilda irmã; as salas de funções são compartilhadas.",
  ["En el de tu juego: español, inglés, alemán, francés, italiano, portugués o ruso. Para otro, en Administración, «Idioma del addon», o escribe /bg idioma en. Se aplica al recargar la interfaz."] = "No do seu jogo: espanhol, inglês, alemão, francês, italiano, português ou russo. Para outro, vá em Administração, «Idioma do addon», ou digite /bg idioma pt. Vale ao recarregar a interface.",
  ["En el juego, abre la ventana de tu profesión (por ejemplo, Herrería). BlazonGuild te pregunta si quieres que tu hermandad lo vea: di «Publicar»."] = "No jogo, abra a janela da sua profissão (por exemplo, Ferraria). O BlazonGuild pergunta se você quer que sua guilda a veja: diga «Publicar».",
  ["En el mapa"] = "No mapa",
  ["En el modo capturas no se hace nada en el juego: es solo una hermandad de ejemplo."] = "No modo capturas nada é feito no jogo: é só uma guilda de exemplo.",
  ["En el nivel máximo"] = "No nível máximo",
  ["En inglés y los demás idiomas: los títulos del Tablón y el Calendario, el oro de la Tesorería, la Arena, los grupos y la Sala de guerra ya salen traducidos."] = "Em inglês e nos outros idiomas: os títulos do Mural e do Calendário, o ouro da Tesouraria, a Arena, os grupos e a Sala de guerra agora aparecem traduzidos.",
  ["En juego"] = "Em jogo",
  ["En juego, %s luchadores. Cada combate lo decide el primer duelo entre los dos."] = "Em jogo, %s lutadores. Cada luta é decidida pelo primeiro duelo entre os dois.",
  ["En juego: cada combate lo decide el primer duelo entre los dos."] = "Em jogo: cada luta é decidida pelo primeiro duelo entre os dois.",
  ["En la Arena, pestaña «Taberna». Tiras seis dados, apartas los que puntúan (unos, cincos, tríos…) y decides si sigues o te plantas. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a 3000."] = "Na Arena, aba «Taverna». Você joga seis dados, separa os que pontuam (uns, cincos, trincas…) e decide se continua ou para. Se uma jogada não der nada, você perde o do turno. Vence quem chegar a 3000.",
  ["En la Arena, pestaña «Torneos», pulsa «Nuevo». La gente se apunta; tú pulsas «Sortear y empezar» y sale el cuadro. Cada combate lo decide su duelo."] = "Na Arena, aba «Torneios», toque em «Novo». As pessoas se inscrevem; você toca em «Sortear e começar» e sai a chave. Cada luta é decidida pelo seu duelo.",
  ["En la Arena: %s."] = "Na Arena: %s.",
  ["En la Arena: %s. "] = "Na Arena: %s. ",
  ["En la Armería de BlazonGuild. Si dices que sí, compartes con tu hermandad lo que llevas puesto (lo mismo que ve quien te inspecciona en el juego), y se pone al día cuando te cambias."] = "No Arsenal do BlazonGuild. Se disser que sim, você compartilha com sua guilda o que está usando (o mesmo que vê quem te inspeciona no jogo), e atualiza quando você troca.",
  ["En la app"] = "No app",
  ["En la final contra %s. Enhorabuena al campeón."] = "Na final contra %s. Parabéns ao campeão.",
  ["En la hermandad"] = "Na guilda",
  ["En la pestaña «En el mapa», «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión, con los metros que faltan."] = "Na aba «No mapa», «Seguir» põe uma seta sob o minimapa que leva você até um colega ou ao ponto de encontro, com os metros que faltam.",
  ["En la pestaña «Quién fabrica qué», escribe el objeto (por ejemplo «poción») y verás quién sabe hacerlo. «Susurrar» abre el chat para hablarle."] = "Na aba «Quem fabrica o quê», escreva o item (por exemplo «poção») e verá quem sabe fazê-lo. «Sussurrar» abre o chat para falar com ele.",
  ["En la próxima entrega del addon"] = "Na próxima versão do addon",
  ["En la raid, pulsa «Grupos» y arrastra a cada uno a su grupo. Cuando la banda esté formada en el juego, «Colocar en la banda» los mueve de verdad."] = "Na raide, toque em «Grupos» e arraste cada um para seu grupo. Quando a raide estiver formada no jogo, «Colocar na raide» os move de verdade.",
  ["En la sección Chat aparecen las pestañas de la alianza: «Toda la alianza» y una por cada hermandad hermana."] = "Na seção Chat aparecem as abas da aliança: «Aliança inteira» e uma para cada guilda irmã.",
  ["En línea"] = "On-line",
  ["En marcha: "] = "Em andamento: ",
  ["En marcha: %s, %s."] = "Em andamento: %s, %s.",
  ["En vivo"] = "Ao vivo",
  ["En vivo, hace %d s"] = "Ao vivo, há %d s",
  ["En «Avistamientos» preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora."] = "Em «Avistamentos» você pergunta onde um jogador da outra facção foi visto. Respondem os colegas que aceitam, com o que viram no último quarto de hora.",
  ["En «Encargos», pide el objeto. El artesano pulsa «Lo hago» y luego «Hecho»; cuando lo tengas, pulsa «Recibido». Te avisamos en cada paso."] = "Em «Encomendas», peça o item. O artesão toca em «Eu faço» e depois em «Feito»; quando você o tiver, toque em «Recebido». Avisamos a cada passo.",
  ["En «Retos» retas a quien esté conectado; si acepta, os avisamos. «Cara a cara» pone a dos luchadores frente a frente, con su vida en directo si están cerca. Sin oro."] = "Em «Desafios» você desafia quem está conectado; se aceitar, avisamos os dois. O «Cara a cara» põe dois lutadores frente a frente, com a vida ao vivo se estiverem perto. Sem ouro.",
  ["En «Retos» ves quién está conectado y puedes retarle. Si acepta, os avisamos a los dos. Aquí no se apuesta oro."] = "Em «Desafios» você vê quem está conectado e pode desafiá-lo. Se aceitar, avisamos os dois. Aqui não se aposta ouro.",
  ["En «Torneos», cualquiera crea uno. Cada uno se apunta; quien lo dirige sortea con /roll y sale el cuadro. Cada combate lo decide el duelo entre los dos."] = "Em «Torneios», qualquer um cria um. Cada um se inscreve; quem dirige sorteia com /roll e sai a chave. Cada luta é decidida pelo duelo entre os dois.",
