  ["La temporada %s se cierra y se guarda con su campeón y su podio."] = "A temporada %s se encerra e é guardada com seu campeão e seu pódio.",
  ["La ventana de BlazonGuild, sus diálogos y sus avisos"] = "A janela do BlazonGuild, seus diálogos e avisos",
  ["La ventana «Cara a cara»"] = "A janela «Cara a cara»",
  ["Las Mazmorras"] = "O Cárcere",
  ["Las Minas de la Muerte"] = "As Minas Mortas",
  ["Las capas"] = "As camadas",
  ["Las cartas del líder de la alianza son para los maestros y los capitanes de cada hermandad."] = "As cartas do líder da aliança são para os mestres e capitães de cada guilda.",
  ["Las decisiones finales de moderación siguen siendo del maestro."] = "As decisões finais de moderação continuam sendo do mestre.",
  ["Las demás hermandades ya lo saben."] = "As outras guildas já sabem.",
  ["Las hermandades de vuestra facción que juegan con BlazonGuild y publican sus cifras. Se conocen al jugar en grupo con alguien de ellas."] = "As guildas da sua facção que jogam com o BlazonGuild e publicam seus números. Vocês as conhecem ao jogar em grupo com alguém delas.",
  ["Las hermandades la reciben solas; durante un minuto puede perderse algún mensaje."] = "As guildas a recebem sozinhas; durante um minuto alguma mensagem pode se perder.",
  ["Las inscripciones ya están cerradas."] = "As inscrições já estão fechadas.",
  ["Las listas para elegir a alguien ya no salen vacías: se hacen al abrirlas, y si no hay nadie lo dicen."] = "As listas para escolher alguém não abrem mais vazias: são feitas ao abrir e, se não houver ninguém, dizem isso.",
  ["Las marcas"] = "As marcas",
  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "As marcas sobre as placas de nome e o anel no retrato do alvo",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "As masmorras dentro de uma capital são da sua facção; as demais, para todos (As Minas Mortas e o Bastião Presa Negra agora aparecem para as duas facções).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "As masmorras e raides agora são as do WoW Forever: suas 9 masmorras novas (Hall of Thanes, Ruínas de Lordaeron, City of Dalaran, Blackmaw Hold…) e suas três raides, The Barrow Deeps, Hyjal Summit e Covil da Onyxia, com os nomes do jogo.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "As outras guildas ainda não disseram quantos vão.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "As outras guildas não te verão conectado. As mensagens de «Mestres» de outras guildas não chegarão enquanto você continuar oculto.",
  ["Las otras hermandades vuelven a verte conectado."] = "As outras guildas voltam a te ver conectado.",
  ["Las próximas dos semanas"] = "As próximas duas semanas",
  ["Las próximas dos semanas (%s)"] = "As próximas duas semanas (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "As raides são compartilhadas entre os addons da sua guilda. Para criá-las, vê-las e se inscrever, aceite antes a privacidade.",
  ["Las salas de roles y el comercio se comparten con todas."] = "As salas de funções e o comércio são compartilhados com todas.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "Perguntamos se ele compartilha; esperando a resposta.",
  ["Le toca a %s%s"] = "É a vez de %s%s",
  ["Le toca a %s…"] = "É a vez de %s…",
  ["Levantar bandera"] = "Erguer bandeira",
  ["Libro"] = "Livro",
  ["Libro de la tesorería"] = "Livro da tesouraria",
  ["Libro para todos: %s"] = "Livro para todos: %s",
  ["Liderazgo"] = "Liderança",
  ["Llamada a los oficiales"] = "Chamado aos oficiais",
  ["Llamar a los oficiales"] = "Chamar os oficiais",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "Chegou através de %s. «Convidar» manda o convite do jogo; «Não» diz isso com educação.",
  ["Lleva un tabardo."] = "Usa um tabardo.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "Anotado pelo addon de %s, que perdeu: só quem perde anota a luta, para que ninguém se dê vitórias.",
  ["Lo comparte él mismo (%s)."] = "Ele mesmo compartilha (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "Ele compartilha: você vê mesmo de longe.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Quem tem o addon compartilha na hora; do resto chega pela web através do app ponte.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Os membros com o addon compartilham; do resto, a Battle.net pela web.",
  ["Lo decide el maestro. Ahora: %s"] = "O mestre decide. Agora: %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "O primeiro duelo decide: clique direito no retrato do outro, «Duelo».",
  ["Lo hace %s."] = "%s faz.",
  ["Lo hago"] = "Eu faço",
  ["Lo lleva %s"] = "Quem tem é %s",
  ["Lo pide %s. %s%s"] = "Pedido por %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "Você pode mudar quando quiser no Arsenal.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "Você pode desligar quando quiser no Arsenal («Compartilhar meu equipamento»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "O que qualquer um diz no chat da guilda, tenha ou não o addon. O que foi dito enquanto você não estava, um companheiro com BlazonGuild te passa.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "O que o próprio jogo diz de você e conta para a guilda: seus duelos com companheiros, quem te mata em JxJ fora das masmorras, o ouro que você dá a um tesoureiro e os chefes que vocês matam juntos.",
  ["Lo que la hermandad debe saber"] = "O que a guilda deve saber",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "O que você publica, sua guilda vê: quem sabe fazer cada item, para sussurrar ou fazer uma encomenda. Atualiza ao abrir a profissão.",
  ["Lo que responde aquí"] = "O que responde aqui",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "O que sua guilda publicar pelo jogo também poderá ser visto no site do BlazonGuild.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "O que você fizer pelo addon: se inscrever numa raide, publicar um grupo, seu perfil… Cada coisa você decide na hora.",
  ["Lo verás en la Armería en un momento."] = "Você verá no Arsenal em um instante.",
  ["Lo verás todo en /bg."] = "Você verá tudo em /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "Visto pelo próprio cliente de %s (o resumo de morte do jogo).",
  ["Lo viste tú (%s)."] = "Você viu (%s).",
  ["Lo último"] = "O mais recente",
  ["Lo último: %s"] = "Último: %s",
  ["Logros"] = "Conquistas",
  ["Los Baldíos"] = "Sertões",
  ["Los Humedales"] = "Pantanal",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "Os inscritos a verão como cancelada. Pode ser reagendada editando-a.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "As mudanças da aliança vão assinadas: ninguém pode falsificá-las.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "Os capitães leem e escrevem em «Oficiais da aliança»; os mensageiros levam as mensagens às outras guildas. Escreva o nome e escolha o cargo.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "Os casos de moderação e os avisos agora ficam só no computador dos organizadores.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "As lutas anteriores continuam guardadas, mas não contam mais.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "Os conectados de cada zona, com ou sem BlazonGuild.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "Os links de itens do chat aparecem bem (antes saíam quebrados), também os já salvos.",
  ["Los grupos"] = "Os grupos",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "Os grupos são compartilhados entre os addons da sua guilda. Aceite a privacidade para vê-los (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "Os chefes das raides são registrados mesmo quando o jogo dá só o nome, e a classificação de guildas agora verifica as fichas das outras.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "Quem move são o líder da raide, quem a criou e os oficiais. Você vê como está.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "Os nomes e o que cada um escreve (notas, anúncios, mensagens) aparecem como estão, sem tradução.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "Os oficiais anotam para quem foi cada item e por quê, para que a próxima raide comece do que já foi decidido. Sem lances nem ouro.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "Os oficiais criam esquadrões pequenos com seu chefe (por exemplo «Os Lobos», de assalto). O chefe escolhe sua gente; o esquadrão tem seu próprio chat.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "Os oficiais de %s já veem. Te convidarão pelo jogo se disserem sim.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "Os oficiais escrevem a ficha pública: o que vocês fazem, idioma, quando jogam e quem procuram (por exemplo, curadores).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "Os organizadores de todas as guildas da aliança. Ninguém mais lê.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "Os organizadores nomeiam árbitros na Arena. Um árbitro pode decidir à mão as lutas de qualquer torneio e tirar um duelo anotado por engano.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Os organizadores podem ver o addon como um membro («Ver como membro»), e outros addons podem ler o BlazonGuild se você permitir.",
