  ["Más tarde"] = "Mais tarde",
  ["Nada"] = "Nada",
  ["Nada en las próximas dos semanas: ni raids de BlazonGuild ni eventos en el calendario del juego. Las raids que cree cualquier miembro en Raids aparecerán aquí."] = "Nada nas próximas duas semanas: nem raides do BlazonGuild nem eventos no calendário do jogo. As raides que qualquer membro criar em Raides aparecerão aqui.",
  ["Nadie"] = "Ninguém",
  ["Nadie (acepta la privacidad para aparecer)"] = "Ninguém (aceite a privacidade para aparecer)",
  ["Nadie ahora. Las peticiones las ven los oficiales."] = "Ninguém agora. Os pedidos são vistos pelos oficiais.",
  ["Nadie ahora. Las peticiones llegan mientras estás conectado; «Invitar» manda la invitación del juego."] = "Ninguém agora. Os pedidos chegam enquanto você está conectado; «Convidar» manda o convite do jogo.",
  ["Nadie coincide con la búsqueda."] = "Ninguém coincide com a busca.",
  ["Nadie comparte ahora su posición. Cada uno lo enciende con «Compartir mi posición»."] = "Ninguém está compartilhando a posição agora. Cada um liga com «Compartilhar minha posição».",
  ["Nadie con recompensa. Cuando alguien de la otra facción mate a un miembro fuera de mazmorras, aparecerá aquí por sí solo."] = "Ninguém com recompensa. Quando alguém da outra facção matar um membro fora de masmorras, aparecerá aqui sozinho.",
  ["Nadie conectado ahora mismo."] = "Ninguém conectado agora.",
  ["Nadie de la hermandad se llama así. Borra lo escrito para ver a todos."] = "Ninguém da guilda tem esse nome. Apague o que escreveu para ver todos.",
  ["Nadie de la lista sabe hacer «%s». En «Encargos» puedes pedirlo a quien sepa."] = "Ninguém da lista sabe fazer «%s». Em «Encomendas» você pode pedir a quem souber.",
  ["Nadie de «%s» conectado ahora, o el nombre no es exacto."] = "Ninguém de «%s» conectado agora, ou o nome não está exato.",
