  ["Nadie en la hermandad."] = "Ninguém na guilda.",
  ["Nadie en reserva."] = "Ninguém na reserva.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán con BlazonGuild las hermandades de este canal."] = "Ninguém escreveu aqui ainda. Comece você: as guildas deste canal lerão com BlazonGuild.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán los miembros con BlazonGuild."] = "Ninguém escreveu aqui ainda. Comece você: os membros com BlazonGuild lerão.",
  ["Nadie ha levantado bandera. Levanta la tuya arriba y la hermandad sabrá que buscas grupo."] = "Ninguém ergueu bandeira. Erga a sua aí em cima e a guilda saberá que você procura grupo.",
  ["Nadie lo ha visto todavía."] = "Ninguém viu ainda.",
  ["Nadie lo tenía."] = "Ninguém tinha.",
  ["Nadie lo tenía. Mañana, más boletos gratis."] = "Ninguém tinha. Amanhã, mais bilhetes grátis.",
  ["Nadie más conectado ahora mismo."] = "Mais ninguém conectado agora.",
