  ["Te toca: tira %d %s"] = "Sua vez: jogue %d %s",
  ["Te trajo: %s. Puedes cambiarlo."] = "Te trouxe: %s. Você pode mudar.",
  ["Templo de Ahn'Qiraj"] = "Templo de Ahn'Qiraj",
  ["Templo de Atal'Hakkar"] = "O Templo de Atal'Hakkar",
  ["Temporada %s"] = "Temporada %s",
  ["Temporada %s%s: %s%s"] = "Temporada %s%s: %s%s",
  ["Temporada %s: campeón %s%s."] = "Temporada %s: campeão %s%s.",
  ["Tendréis un chat común, con una pestaña para cada hermandad."] = "Vocês terão um chat comum, com uma aba para cada guilda.",
  ["Tenías una ficha en %s (tu presentación, tu rol, cuándo juegas)."] = "Você tinha uma ficha em %s (sua apresentação, sua função, quando joga).",
  ["Tercer aviso: %s"] = "Terceiro aviso: %s",
  ["Termina antes tu partida."] = "Termine antes sua partida.",
  ["Terminada"] = "Terminada",
  ["Terminado"] = "Terminado",
  ["Terminar"] = "Terminar",
  ["Terminar y guardar el parte"] = "Terminar e salvar o relatório",
  ["Tesoreros (nombres separados por comas)"] = "Tesoureiros (nomes separados por vírgulas)",
  ["Tesoreros: %s. "] = "Tesoureiros: %s. ",
  ["Tesorería"] = "Tesouraria",
  ["Tesorería: el oro se escribe también como 2g 50s. Autoprueba: dice cómo escribe tu juego los nombres."] = "Tesouraria: o ouro também pode ser escrito como 2g 50s. Autoteste: diz como o seu jogo escreve os nomes.",
  ["Tesorería: las cantidades ya caben en sus cuadros. Rankings: los 10 primeros de cada honor, y ya no está el del nivel 60."] = "Tesouraria: as quantias agora cabem nos seus quadros. Rankings: os 10 primeiros de cada honra, e o do nível 60 não está mais.",
  ["Texto (opcional)"] = "Texto (opcional)",
  ["The Barrow Deeps"] = "The Barrow Deeps",
  ["Tiene que estar cerca de ti (tu objetivo, el ratón encima o en tu grupo)."] = "Ele precisa estar perto de você (seu alvo, sob o mouse ou no seu grupo).",
  ["Tiene que estar conectado y con BlazonGuild."] = "Tem que estar conectado e com BlazonGuild.",
  ["Tienes la palabra"] = "Você tem a palavra",
  ["Tienes que ser líder o ayudante de la banda."] = "Você tem que ser líder ou assistente da raide.",
  ["Tierras Inhóspitas"] = "Ermos",
  ["Tierras de la Peste del Este"] = "Terras Pestilentas Orientais",
  ["Tierras de la Peste del Oeste"] = "Terras Pestilentas Ocidentais",
  ["Tipo %s"] = "Tipo %s",
  ["Tira los dados."] = "Jogue os dados.",
  ["Tira los que quedan, o plántate y súmalo."] = "Jogue o resto, ou pare e some.",
  ["Tira seis dados, aparta los que puntúan y decide: arriesgar con el resto o plantarte. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a %s. Los dados salen del /roll del juego."] = "Jogue seis dados, separe os que pontuam e decida: arriscar com o resto ou parar. Se uma jogada não der nada, você perde o do turno. Vence quem chegar a %s. Os dados saem do /roll do jogo.",
  ["Tirando…"] = "Jogando…",
  ["Tirar"] = "Jogar",
  ["Tirar %d %s"] = "Jogar %d %s",
  ["Tirar %s%s"] = "Jogar %s%s",
  ["Toda la alianza"] = "Aliança inteira",
  ["Toda la alianza, de «%s»"] = "Toda a aliança, de «%s»",
  ["Toda la hermandad"] = "Guilda inteira",
  ["Todavía no ha escrito nada sobre sí."] = "Ainda não escreveu nada sobre si.",
  ["Todavía no has escrito nada. Pulsa «Editar mi ficha»."] = "Você ainda não escreveu nada. Toque em «Editar minha ficha».",
  ["Todavía no hay mensajes en esta sesión. Lo que se diga en el chat de hermandad aparecerá aquí."] = "Ainda não há mensagens nesta sessão. O que for dito no chat da guilda aparecerá aqui.",
  ["Todavía no hay raids programadas en %s."] = "Ainda não há raides agendadas em %s.",
  ["Todos"] = "Todos",
  ["Todos empiezan con %s puntos. Ganar a alguien mejor que tú da más puntos; a alguien de más nivel, también."] = "Todos começam com %s pontos. Vencer alguém melhor que você dá mais pontos; alguém de nível maior, também.",
  ["Todos empiezan con 1500. Ganar a alguien mejor da más puntos. Por ejemplo, en tus primeros combates y con el mismo nivel: ganar a uno de 1600 da unos 26; a uno de 1400, unos 14."] = "Todos começam com 1500. Vencer alguém melhor dá mais pontos. Por exemplo, nas suas primeiras lutas e no mesmo nível: vencer alguém de 1600 dá uns 26; alguém de 1400, uns 14.",
  ["Todos empiezan de cero. ¡Suerte!"] = "Todos começam do zero. Boa sorte!",
  ["Todos los apuntados tienen grupo."] = "Todos os inscritos têm grupo.",
  ["Todos los mensajes de la alianza llevan una marca hecha con su clave. Cámbiala si crees que la conoce alguien de fuera."] = "Todas as mensagens da aliança levam uma marca feita com sua chave. Mude-a se achar que alguém de fora a conhece.",
  ["Todos ven los grupos; los mueven el líder de la raid, quien la creó y los oficiales."] = "Todos veem os grupos; quem os move são o líder da raide, quem a criou e os oficiais.",
  ["Todos vuelven a empezar con %s puntos."] = "Todos voltam a começar com %s pontos.",
  ["Torneo"] = "Torneio",
  ["Torneo, %s"] = "Torneio, %s",
  ["Torneo: %s"] = "Torneio: %s",
  ["Torneo: cada uno se apunta; al sortear sale el cuadro eliminatorio."] = "Torneio: cada um se inscreve; ao sortear sai a chave eliminatória.",
  ["Torneos"] = "Torneios",
  ["Torneos y veladas"] = "Torneios e noites",
  ["Traerla"] = "Trazê-la",
  ["Tres iguales: la cara × 100 (tres 4 = 400); tres 1 = 1000. Cada dado igual de más lo dobla."] = "Três iguais: a face × 100 (três 4 = 400); três 1 = 1000. Cada dado igual a mais dobra.",
