  ["«%s»: %s hermandades, en contacto con %s"] = "«%s»: %s guildas, em contato com %s",
  ["«Cara a cara» pone a dos luchadores uno frente al otro, con su vida en directo si los tienes cerca y quién gana al acabar. Se puede agrandar para retransmitir."] = "O «Cara a cara» põe dois lutadores frente a frente, com a vida ao vivo se estiverem perto e quem vence no fim. Dá para aumentar para transmitir.",
  ["«Colocar en la banda» mueve a la gente a sus grupos de verdad cuando la banda ya está formada (líder o ayudante, fuera de combate)."] = "«Colocar na raide» move as pessoas para seus grupos de verdade quando a raide já está formada (líder ou assistente, fora de combate).",
  ["«Copiar» y luego Ctrl+C: pégalo donde quieras."] = "«Copiar» e depois Ctrl+C: cole onde quiser.",
  ["«Grupos» enseña los grupos de la banda como en el juego. El líder de la raid, quien la creó y los oficiales arrastran a cada uno a su grupo y su fila (o lo pulsan y luego pulsan dónde va)."] = "«Grupos» mostra os grupos da raide como no jogo. O líder da raide, quem a criou e os oficiais arrastam cada um para seu grupo e sua linha (ou tocam nele e depois onde vai).",
  ["«Invitar confirmados» invita a los que van y están conectados, y convierte el grupo en banda."] = "«Convidar confirmados» convida quem vai e está conectado, e transforma o grupo em raide.",
  ["«Mazmorras» ahora se llama Grupos: también para JcJ, misiones, subir de nivel o farmear."] = "«Masmorras» agora se chama Grupos: também para JxJ, missões, subir de nível ou farmar.",
  ["«Retar» le manda tu reto; el duelo lo empezáis desde el juego."] = "«Desafiar» manda seu desafio; o duelo vocês começam pelo jogo.",
  ["«Se busca»"] = "«Procurados»",
  ["«Ver su ficha» en el menú del botón derecho del juego"] = "«Ver a ficha» no menu do clique direito do jogo",
  ["«Ver un duelo» (o /bg duelo): el cara a cara del duelo de tu objetivo. Y en cada torneo o velada, «Cara a cara del siguiente combate»."] = "«Ver um duelo» (ou /bg duelo): o cara a cara do duelo do seu alvo. E em cada torneio ou noite de lutas, «Cara a cara da próxima luta».",
  ["«¡A las armas!» y «Reunión aquí» para los organizadores, con alerta y marca en el mapa."] = "«Às armas!» e «Reunião aqui» para os organizadores, com alerta e marca no mapa.",
